n_queens.brute:
boards = empty list
for each permutation columns of 0 .. n - 1:   (columns[row] = the column of that row's queen)
    if no pair i < j has |columns[i] - columns[j]| == j - i:   (no shared diagonal)
        append the board drawn from columns to boards
return boards

sudoku_solver.brute:
legal(row, col, digit): digit appears nowhere in row, column col or the 3x3 box of (row, col)
solve_first_empty():
    for each cell (row, col) in row-major order:
        if board[row][col] is empty:
            for each digit from 1 to 9:
                if legal(row, col, digit):
                    board[row][col] = digit
                    if solve_first_empty(): return true
                    board[row][col] = empty
            return false   (no digit fits here: backtrack)
    return true
solve_first_empty()

remove_invalid_parentheses.optimal:
left = right = 0   (forced removals of '(' and ')')
for each c in s: if '(' then left += 1; if ')' then left -= 1 when left > 0 else right += 1
results = empty set
choose(i, open, left, right, path):
    if i == n: if open == 0 and left == 0 and right == 0: add path to results; return
    c = s[i]
    if c == '(' and left > 0: choose(i + 1, open, left - 1, right, path)   (delete it)
    if c == ')' and right > 0: choose(i + 1, open, left, right - 1, path)
    if c == '(': choose(i + 1, open + 1, left, right, path + c)   (keep it)
    else if c == ')': if open > 0: choose(i + 1, open - 1, left, right, path + c)
    else: choose(i + 1, open, left, right, path + c)
choose(0, 0, left, right, "")
return results as a list

expression_add_operators.brute:
result = empty list
for each way to put '', '+', '-' or '*' in the n - 1 gaps between digits:
    expr = num with those separators inserted
    if some operand has a leading zero: skip
    if expr evaluates to target: append expr to result   (full re-parse at every leaf)
return result

twenty_four_game.brute:
for each ordering of the 4 cards as exact fractions:
    for each choice of 3 operators from + - * /:
        for each of the 5 bracketing shapes:
            if evaluating the shape gives 24 (skipping division by zero): return true
return false

twenty_four_game.optimal:
solve(numbers):
    if one number left: return |numbers[0] - 24| < epsilon
    for each pair i < j:
        a = numbers[i], b = numbers[j], rest = the other numbers
        results = [a + b, a - b, b - a, a * b], plus a / b if b != 0, plus b / a if a != 0
        for each value in results:
            if solve(rest + [value]): return true   (merge the pair, recurse on one fewer number)
    return false
